#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ConsolidationSessionStatus {
    AwaitingCommitments,
    AwaitingAuthorization,
    AwaitingShares,
    Closed,
}

